// Posters and validation are generated by default; pass --video to also export MP4.
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {spawn} from 'node:child_process';
import {once} from 'node:events';
import assert from 'node:assert/strict';
import sharp from 'sharp';
const dir=path.dirname(fileURLToPath(import.meta.url)),bundle=path.resolve(process.argv[2]);
const temp=path.join(dir,'temp/image-paths'),out=path.resolve(dir,'../IMAGE/07-SW-Overview');
const trace=JSON.parse(await fs.readFile(path.join(dir,'image-path-trace.txt'),'utf8'));
const variant=JSON.parse(await fs.readFile(path.join(dir,'image-path-variant.txt'),'utf8'));
// This movie displays opaque RGB cells: the actual retained background must
// survive partial redraws, including anti-aliased rotation edges.
for(const t of [trace,variant])for(const s of t.stages)
 for(let y=0;y<t.h;y++)for(let x=0;x<t.w;x++)
  assert.equal(s.pixels[y*t.stride+x]>>>24,255,`${s.name}: transparent Surface pixel (${x},${y})`);
const source=await fs.readFile(path.join(dir,'sw-image-paths.lua'),'utf8');
const lua=v=>Array.isArray(v)?'{'+v.map(lua).join(',')+'}':v&&typeof v==='object'?'{'+Object.entries(v).map(([k,v])=>`${k}=${lua(v)}`).join(',')+'}':JSON.stringify(v);
assert(source.includes('local trace='+lua(trace)));
const {createTMath}=await import(pathToFileURL(path.join(bundle,'client.js')));
const runtime=await createTMath('return tmath.scene{theme="pro_white"}','bootstrap.lua',{renderEngine:'cpu',wasmBinary:await fs.readFile(path.join(bundle,'tmath-wasm.wasm'))});
runtime.font('Pretendard',await fs.readFile(path.join(bundle,'Pretendard.ttf')));
const rgb=v=>[v&255,(v>>>8)&255,(v>>>16)&255];
let checks=0;
const at=(b,w,x,y)=>[...b.subarray((Math.floor(y)*w+Math.floor(x))*4,(Math.floor(y)*w+Math.floor(x))*4+3)];
const eq=(a,b,id)=>{assert(a.every((v,i)=>Math.abs(v-b[i])<=1),`${id}: ${a}/${b}`);checks++;};
try {
 runtime.loadLua(source,'sw-image-paths.lua');
 const [width,height]=runtime.size(),duration=runtime.duration,frames=Math.ceil(duration*30)+1;
 let margin=Infinity;const labels=new Set();
 for(let f=0;f<frames;f++) {
  const objs=runtime.layoutReport(Math.min(f/30,duration),4).objects,texts=[];
  for(const o of objs) {
   if(o.type==='text')assert(o.id.startsWith('label_'));
   if(!o.visible||o.type==='group')continue;
   const b=o.paintBounds;assert(b&&b.width>0&&b.height>0);
   const m=Math.min(b.x,b.y,width-b.x-b.width,height-b.y-b.height);margin=Math.min(margin,m);assert(m>=4,'overflow '+o.id);
   if(o.type==='text'){texts.push(o);labels.add(o.id);}
  }
  for(let i=0;i<texts.length;i++)for(let j=i+1;j<texts.length;j++) {
   const a=texts[i].paintBounds,b=texts[j].paintBounds;
   assert(Math.max(a.x-b.x-b.width,b.x-a.x-a.width)>=4||Math.max(a.y-b.y-b.height,b.y-a.y-a.height)>=4,'text gap');
  }
 }
 let memory=new Array(trace.stride*trace.h).fill(trace.background);
 const check=(time,label)=>{
  const b=Buffer.from(runtime.render(time,true));
  for(let y=0;y<trace.h;y++)for(let x=0;x<trace.w;x++)eq(at(b,width,850+(x+.5)*32,160+(y+.5)*32),rgb(memory[y*trace.stride+x]),label);
  for(let y=0;y<trace.ih;y++)for(let x=0;x<trace.iw;x++)eq(at(b,width,120+(x+.5)*40,350+(y+.5)*40),rgb(trace.source[y*trace.iw+x]),'source retained');
 };
 check(0,'initial');let time=.8;const samples=[0];
 for(const [i,s] of trace.stages.entries()) {
  assert.equal(s.hasRle,false);assert.equal(s.clips,0);
  if(i){time+=.15+.20;memory.fill(trace.background);check(time-.001,'reset');}
  samples.push(time+.5);time+=.30+.5+.15;
  if(i===2) {
   assert.deepEqual(s.triangles.map(t=>t.indices),[[0,1,3],[1,2,3]]);
   time+=.2+.6+.1;
   for(const [k,triangle] of s.triangles.entries()) {
    time+=.15+.4+.1;
    const before=memory.slice();
    for(let y=0;y<trace.h;y++) {
     if(!Array.from({length:trace.w},(_,x)=>y*trace.stride+x).some(at=>triangle.pixels[at]!==before[at]))continue;
     time+=.04+.14;
     for(let x=0;x<trace.w;x++)memory[y*trace.stride+x]=triangle.pixels[y*trace.stride+x];
     check(time+.02,`triangle ${k+1} row ${y}`);time+=.06+.04;
    }
    assert.deepEqual(memory,triangle.pixels);samples.push(time+.2);time+=.7+.12;
   }
   assert.deepEqual(memory,s.pixels);
  } else {
  for(let y=0;y<trace.h;y++) {
   time+=.04+.08;
   for(let x=0;x<trace.w;x++)memory[y*trace.stride+x]=s.pixels[y*trace.stride+x];
   check(time+.02,`${s.name} row ${y}`);
   time+=.04+.04;
  }
  }
  samples.push(time+.5);time+=i===trace.stages.length-1?3:1.5;
 }
 assert(Math.abs(time-duration)<.002,'timeline');check(duration,'final');
 runtime.loadLua(source.replace('local trace='+lua(trace),'local trace='+lua(variant)),'image-variant.lua');
 const changed=Buffer.from(runtime.render(runtime.duration,true));
 let differences=0;
 for(let y=0;y<trace.h;y++)for(let x=0;x<trace.w;x++) {
  const ix=y*trace.stride+x;
  eq(at(changed,width,850+(x+.5)*32,160+(y+.5)*32),rgb(variant.stages[2].pixels[ix]),'45-degree engine variant');
  if(variant.stages[2].pixels[ix]!==trace.stages[2].pixels[ix])differences++;
 }
 assert(differences>10);runtime.loadLua(source,'sw-image-paths.lua');
 const report={width,height,duration,frames,framesAudited:frames,labels:labels.size,minMargin:margin,pixelChecks:checks,variantDifferences:differences,noRleStages:trace.stages.map(s=>s.name)};
 console.log(JSON.stringify(report));await fs.writeFile(path.join(temp,'review.txt'),JSON.stringify(report,null,2)+'\nNo additional inline raster review or manual playback.\n');
 for(const [i,t] of samples.entries())await sharp(Buffer.from(runtime.render(t,true)),{raw:{width,height,channels:4}}).png().toFile(path.join(temp,'review-'+i+'.png'));
 await sharp(Buffer.from(runtime.render(duration,true)),{raw:{width,height,channels:4}}).webp({lossless:true}).toFile(path.join(out,'image-paths.webp'));
 if(!process.argv.includes('--preview') && process.argv.includes('--video')) {
  const ff=spawn('ffmpeg',['-hide_banner','-loglevel','error','-y','-f','rawvideo','-pixel_format','rgba','-video_size',`${width}x${height}`,'-framerate','30','-i','pipe:0','-an','-c:v','libx264','-preset','medium','-crf','20','-pix_fmt','yuv420p','-movflags','+faststart',path.join(out,'image-direct-scale-rotation.mp4')],{stdio:['pipe','inherit','inherit']});
  const end=once(ff,'close');
  for(let f=0;f<frames;f++){if(!ff.stdin.write(Buffer.from(runtime.render(Math.min(f/30,duration),true))))await once(ff.stdin,'drain');if(f%180===0)console.log(`${f}/${frames}`);}
  ff.stdin.end();const [code]=await end;assert.equal(code,0);
 }
}finally{runtime.destroy();}
